$issuedCase=static function(string $tag)use($db):array{
    ownBankGroupDatabase($db);$club='own-return-issued-'.$tag;$actor=$club.'-admin';$db->prepare('INSERT INTO clubs VALUES(?,?)')->execute([$club,'Own continuing issued invoice']);$db->prepare("INSERT INTO actors(id,club_id,role,is_superuser) VALUES(?,?,'member',1)")->execute([$actor,$club]);return ownPaymentReturnIssuedCase($db,$actor,$tag);
