$issued=$issuedCase('continuing');$ledger=$issued['finance'];$docs=new Documents($db,$issued['actor']);$invoiceBefore=$issued['invoices']->get($issued['invoice']);$file=$docs->file($invoiceBefore['document_id'],1);$requestReason="\nOwn full returned invoice payment; original demand valid0 ä🙂\r\n";$preview=$ledger->paymentReturnReview($issued['source'],$issued['returned'],$requestReason);$check($preview['review']['source']['eligible']&&$preview['review']['source']['issued_originals'][$issued['entry']]['invoice']['id']===$issued['invoice'],'actual issued original invoice can retain its valid demand after full payment returns');$input=[$issued['source'],(int)$preview['review']['source']['transaction']['version'],$issued['returned'],(int)$preview['review']['returned']['version'],$requestReason,$key(),$preview['hash'],true];$ledger->returnPayment(...$input);
$check($issued['invoices']->get($issued['invoice'])===$invoiceBefore&&$docs->file($invoiceBefore['document_id'],1)===$file&&$ledger->entry($issued['entry'])['payment_state']==='open','actual full returned invoice payment preserves whole issued invoice payload history and exact original PDF while reopening its original demand');$before=$whole();$reminder=ReminderSource::read($db,$issued['actor'],$issued['invoice'],'2026-01-12');$mail=OutgoingMailContext::read($db,$issued['actor'],$issued['invoice']);$check($reminder['open_cents']===10000&&$reminder['original_pdf']===$file['bytes']&&$mail['payment']['open_cents']===10000&&$mail['values']['ZAHLBETRAG']==='100,00 €'&&$whole()===$before,'actual original invoice reminder and mail readers recover the full valid100 demand with unchanged original PDF without a queued or sent message');
$ledger->recordPayment($issued['entry'],(int)$ledger->entry($issued['entry'])['version'],$issued['account'],'2026-01-13');$before=$whole();$check($ledger->returnPayment(...$input)['replayed']&&$whole()===$before&&$docs->file($invoiceBefore['document_id'],1)===$file,'actual invoice recollection keeps the accepted earlier returned-payment first and issued PDF exact');$deny(fn()=>ReminderSource::read($db,$issued['actor'],$issued['invoice'],'2026-01-14'),'actual fully recollected original invoice no longer supports a false payment reminder');

$credited=$issuedCase('has-credit');$credit=$credited['invoices']->correct($credited['invoice'],3,'credit','30','Own actual legal credit requires its separate refund','2026-01-12',$key());$creditEntry=$credited['invoices']->get($credit)['entry_id'];$before=$whole();$deny(fn()=>$credited['finance']->paymentReturnReview($credited['source'],$credited['returned'],'Own full return must not invalidate a legitimate credit refund source'),'actual issued credit prevents reopening the whole original invoice through a payment return');$creditProof=CreditRefundSource::originals($db,$credited['actor'],$creditEntry);$check((int)$creditProof['parent']['entry']['allocated_cents']===10000&&$whole()===$before,'refused whole return preserves actual credit refund original paid100 cap all legal credit rows and original PDF');

$staleInvoice=$issuedCase('later-credit');$ledger=$staleInvoice['finance'];$preview=$ledger->paymentReturnReview($staleInvoice['source'],$staleInvoice['returned'],'Own earlier actual invoice return review');$input=[$staleInvoice['source'],(int)$preview['review']['source']['transaction']['version'],$staleInvoice['returned'],(int)$preview['review']['returned']['version'],'Own earlier actual invoice return review',$key(),$preview['hash'],true];$staleInvoice['invoices']->correct($staleInvoice['invoice'],3,'credit','30','Own independently accepted legal credit','2026-01-12',$key());$before=$whole();$deny(fn()=>$ledger->returnPayment(...$input),'genuinely later issued credit invalidates an earlier full returned-payment review');$check($whole()===$before,'late legal credit refusal retains every whole independently committed invoice credit PDF payment and allocation');
